// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Callback invoked for each element of an adjacency list.
*
* @param value - list element
* @param i - list element index
* @returns list of vertices
*/
type AdjacencyListCallback = ( value: unknown, i: number ) => ArrayLike<number>;

/**
* Callback invoked for each element of a list of edges.
*
* @param value - list element
* @param i - list element index
* @returns list of vertices specifying a directed edge
*/
type EdgeCallback = ( value: unknown, i: number ) => ArrayLike<number>;

/**
* Compact adjacency matrix.
*/
interface CompactAdjacencyMatrix {
	/**
	* Adds a directed edge between two vertices.
	*
	* @param i - starting vertex
	* @param j - ending vertex
	* @throws first argument must be a nonnegative integer
	* @throws second argument must be a nonnegative integer
	* @throws first argument must not exceed matrix dimensions
	* @throws second argument must not exceed matrix dimensions
	* @returns adjacency matrix instance
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*/
	addEdge( i: number, j: number ): CompactAdjacencyMatrix;

	/**
	* Returns the list of all edges.
	*
	* @returns list of edges
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var edges = adj.edges;
	* // returns [ [ 0, 1 ], [ 0, 2 ], [ 1, 2 ], [ 2, 3 ] ]
	*/
	readonly edges: Array<Array<number>>;

	/**
	* Checks whether a directed edge exists between two vertices.
	*
	* @param i - starting vertex
	* @param j - ending vertex
	* @throws first argument must be a nonnegative integer
	* @throws second argument must be a nonnegative integer
	* @throws first argument must not exceed matrix dimensions
	* @throws second argument must not exceed matrix dimensions
	* @returns boolean indicating if an edge exists
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	*
	* var bool = adj.hasEdge( 0, 1 );
	* // returns true
	*
	* bool = adj.hasEdge( 1, 3 );
	* // returns false
	*/
	hasEdge( i: number, j: number ): boolean;

	/**
	* Returns the indegree of a vertex (i.e., number of edges ending at a vertex).
	*
	* @param j - vertex
	* @throws must provide a nonnegative integer
	* @throws must not exceed matrix dimensions
	* @returns indegree
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var d = adj.inDegree( 2 );
	* // returns 2
	*/
	inDegree( j: number ): number;

	/**
	* Returns a list of vertices having edges ending at a specified vertex.
	*
	* @param j - vertex
	* @throws must provide a nonnegative integer
	* @throws must not exceed matrix dimensions
	* @returns list of vertices
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var e = adj.inEdges( 2 );
	* // returns [ 0, 1 ]
	*/
	inEdges( j: number ): Array<number>;

	/**
	* Returns the total number of edges.
	*
	* @returns total number of edges
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	*
	* var M = adj.nedges;
	* // returns 3
	*/
	readonly nedges: number;

	/**
	* Returns the total number of vertices.
	*
	* @returns total number of vertices
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* var N = adj.nvertices;
	* // returns 4
	*/
	readonly nvertices: number;

	/**
	* Returns the outdegree of a vertex (i.e., number of edges starting at a vertex).
	*
	* @param i - vertex
	* @throws must provide a nonnegative integer
	* @throws must not exceed matrix dimensions
	* @returns outdegree
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var d = adj.outDegree( 2 );
	* // returns 1
	*/
	outDegree( i: number ): number;

	/**
	* Returns a list of vertices having edges starting at a specified vertex.
	*
	* @param i - vertex
	* @throws must provide a nonnegative integer
	* @throws must not exceed matrix dimensions
	* @returns list of vertices
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var e = adj.outEdges( 2 );
	* // returns [ 3 ]
	*/
	outEdges( i: number ): Array<number>;

	/**
	* Removes a directed edge between two vertices.
	*
	* @param i - starting vertex
	* @param j - ending vertex
	* @throws first argument must be a nonnegative integer
	* @throws second argument must be a nonnegative integer
	* @throws first argument must not exceed matrix dimensions
	* @throws second argument must not exceed matrix dimensions
	* @returns adjacency matrix instance
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	*
	* adj.removeEdge( 0, 1 );
	* adj.removeEdge( 0, 2 );
	*/
	removeEdge( i: number, j: number ): CompactAdjacencyMatrix;

	/**
	* Returns an adjacency list representation.
	*
	* @returns adjacency list representation
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 0, 1 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var list = adj.toAdjacencyList();
	* // returns [ [ 1, 2 ], [ 2 ], [ 3 ], [] ]
	*/
	toAdjacencyList(): Array<Array<number>>;

	/**
	* Returns a topological ordering of the directed graph.
	*
	* ## Notes
	*
	* -   The function returns a two-element array.
	* -   If the function is able to compute a topological ordering, the first array element is the topological ordering and the second element is `null`.
	* -   If a topological ordering cannot be achieved (e.g., due to the graph not being a directed acyclic graph (DAG)), the first array element is `null` and the second element is the first encountered cycle.
	*
	* @returns results
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	*
	* adj.addEdge( 1, 0 );
	* adj.addEdge( 1, 2 );
	* adj.addEdge( 0, 2 );
	* adj.addEdge( 2, 3 );
	*
	* var results = adj.toposort();
	* // returns <Array>
	*
	* var order = results[ 0 ];
	* // returns [ 1, 0, 2, 3 ]
	*
	* var cycle = results[ 1 ];
	* // returns null
	*/
	toposort(): [ Array<number> | null, Array<number> | null ];
}

/**
* Interface defining a compact adjacency matrix constructor which is both "newable" and "callable".
*/
interface CompactAdjacencyMatrixConstructor {
	/**
	* Compact adjacency matrix constructor.
	*
	* @param N - number of vertices
	* @throws must provide a nonnegative integer
	* @returns adjacency matrix instance
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	* // returns <CompactAdjacencyMatrix>
	*
	* @example
	* var adj = CompactAdjacencyMatrix( 4 );
	* // returns <CompactAdjacencyMatrix>
	*/
	( N: number ): CompactAdjacencyMatrix;

	/**
	* Compact adjacency matrix constructor.
	*
	* @param N - number of vertices
	* @throws must provide a nonnegative integer
	* @returns adjacency matrix instance
	*
	* @example
	* var adj = new CompactAdjacencyMatrix( 4 );
	* // returns <CompactAdjacencyMatrix>
	*/
	new ( N: number ): CompactAdjacencyMatrix;

	/**
	* Creates a compact adjacency matrix from an adjacency list.
	*
	* ## Notes
	*
	* -   A callback function is provided two arguments: a list element and the list element index.
	* -   A callback function must return a list of vertices.
	*
	* @param list - adjacency list
	* @param clbk - callback to invoke for each list element
	* @param thisArg - callback execution context
	* @returns adjacency matrix instance
	*
	* @example
	* var list = [ [ 1, 2 ], [ 2 ], [ 3 ], [] ];
	*
	* var adj = CompactAdjacencyMatrix.fromAdjacencyList( list );
	* // returns <CompactAdjacencyMatrix>
	*
	* var bool = adj.hasEdge( 0, 1 );
	* // returns true
	*/
	fromAdjacencyList( list: Collection<unknown> | Iterable<unknown>, clbk?: AdjacencyListCallback, thisArg?: unknown ): CompactAdjacencyMatrix;

	/**
	* Creates a compact adjacency matrix from a list of edges.
	*
	* ## Notes
	*
	* -   A callback function is provided two arguments: a list element and the list element index.
	* -   A callback function must return a list of vertices specifying a directed edge.
	*
	* @param N - number of vertices
	* @param edges - list of edges
	* @param clbk - callback to invoke for each list element
	* @param thisArg - callback execution context
	* @returns adjacency matrix instance
	*
	* @example
	* var edges = [ [ 0, 1 ], [ 0, 2 ], [ 1, 2 ], [ 2, 3 ] ];
	*
	* var adj = CompactAdjacencyMatrix.fromEdges( 4, edges );
	* // returns <CompactAdjacencyMatrix>
	*
	* var bool = adj.hasEdge( 0, 1 );
	* // returns true
	*/
	fromEdges( N: number, edges: Collection<unknown> | Iterable<unknown>, clbk?: EdgeCallback, thisArg?: unknown ): CompactAdjacencyMatrix;
}

/**
* Compact adjacency matrix constructor.
*/
declare var ctor: CompactAdjacencyMatrixConstructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: CompactAdjacencyMatrix
